const loginData = $("1. Login to ByteWire API").first().json;
const token = loginData.token;
const allItems = $input.all().map(item => item.json);
const videoList = allItems.length === 1 && Array.isArray(allItems[0]) ? allItems[0] : allItems;

let targetVideoId = null;
let singleShortIndex = null;
let isSingleShort = false;
let isFullVideoOnly = false;
let webhookPayload = null;

try {
  const webhookNode = $("Webhook Trigger (ByteWire Push)").first();
  webhookPayload = webhookNode?.json?.body || webhookNode?.json;
  targetVideoId = webhookPayload?.videoId;
  singleShortIndex = webhookPayload?.shortIndex || webhookPayload?.factIndex;
  isSingleShort = webhookPayload?.action === "post_reel" || webhookPayload?.event === "upload_single_short" || !!singleShortIndex;
  isFullVideoOnly = webhookPayload?.action === "post_full_video" || webhookPayload?.event === "upload_full_video";

  // If 5 AM completion event arrives, DO NOT post to YouTube
  if (webhookPayload?.event === "video.completed" || webhookPayload?.action === "store_only") {
    return [{ json: { skip: true, message: "5:00 AM video generation complete. Upload scheduled for 6 AM (full), 9 AM (Short 1), 2 PM (Short 2), 6 PM (Short 3)." } }];
  }
} catch (_) {}

// If triggered on schedule (or no specific action provided), determine slot by current IST time (UTC+5:30)
if (!webhookPayload || (!isSingleShort && !isFullVideoOnly && !targetVideoId)) {
  const now = new Date();
  const utcHours = now.getUTCHours();
  const utcMins = now.getUTCMinutes();
  const istHours = (utcHours + 5 + Math.floor((utcMins + 30) / 60)) % 24;

  if (istHours >= 5 && istHours < 8) {
    // 6 AM window: upload full video
    isFullVideoOnly = true;
  } else if (istHours >= 8 && istHours < 12) {
    // 9 AM window: upload Short #1
    isSingleShort = true;
    singleShortIndex = 1;
  } else if (istHours >= 12 && istHours < 16) {
    // 2 PM window: upload Short #2
    isSingleShort = true;
    singleShortIndex = 2;
  } else if (istHours >= 16 && istHours < 22) {
    // 6 PM window: upload Short #3
    isSingleShort = true;
    singleShortIndex = 3;
  }
}

let pendingUploads = [];
if (isSingleShort && targetVideoId) {
  pendingUploads = videoList.filter(v => v && String(v._id) === String(targetVideoId));
} else if (isSingleShort) {
  // Find latest completed video where this specific short is not yet uploaded
  pendingUploads = videoList.filter(v => {
    if (!v || v.status !== "Completed") return false;
    const s = (v.shorts || []).find((sh, idx) => Number(sh.factIndex) === Number(singleShortIndex) || (idx + 1) === Number(singleShortIndex));
    return s && !s.isPosted && !s.youtubeShortId;
  });
} else if (targetVideoId) {
  pendingUploads = videoList.filter(v => v && String(v._id) === String(targetVideoId) && !v.youtubeVideoId);
} else {
  // 6:00 AM full video: find latest completed video without youtubeVideoId
  pendingUploads = videoList.filter(v => v && v.status === "Completed" && !v.youtubeVideoId);
}

if (pendingUploads.length === 0) {
  return [{ json: { skip: true, message: "No pending video or short ready for publishing in this time window." } }];
}

const video = pendingUploads[0];
return [{
  json: {
    skip: false,
    isSingleShort: isSingleShort,
    isFullVideoOnly: isFullVideoOnly,
    singleShortIndex: singleShortIndex,
    webhookPayload: webhookPayload,
    videoId: video._id,
    token: token,
    title: video.title,
    subject: video.subject,
    status: video.status,
    youtubeMetadata: video.youtubeMetadata || {},
    shorts: (video.shorts || []).slice(0, 3),
    shortsCount: Math.min(3, (video.shorts || []).length),
    videoUrl: "https://ytvideo.harikothapalli.space/videos/" + video._id + ".mp4",
    thumbnailUrl: "https://ytvideo.harikothapalli.space/thumbnails/" + video._id + ".png"
  }
}];

const video = $input.first().json;
const findPending = $("3. Find Pending Upload").first().json;
const isSingleShort = findPending.isSingleShort;
const isFullVideoOnly = findPending.isFullVideoOnly;
const singleShortIndex = Number(findPending.singleShortIndex) || 1;
const webhookPayload = findPending.webhookPayload || {};
const token = findPending.token;

if (isSingleShort) {
  const shorts = (video.shorts || []).slice(0, 3);
  const short = shorts.find((s, idx) => Number(s.factIndex) === singleShortIndex || (idx + 1) === singleShortIndex) || shorts[0] || {};
  const ytMeta = short.youtubeMetadata || {};
  const factTitle = short.factTitle || short.title || ("News Short #" + singleShortIndex);
  const rawTitle = webhookPayload.title || ytMeta.title || (factTitle + " #Shorts");
  const finalTitle = (rawTitle.includes("#Shorts") || rawTitle.includes("#shorts")) ? rawTitle : (rawTitle.substring(0, 90) + " #Shorts");
  const parentLink = video.youtubeUrl ? ("\n\nFull Video: " + video.youtubeUrl) : "";
  const shortDesc = webhookPayload.description || (ytMeta.description || (short.scriptText || factTitle) + parentLink + "\n\n#shorts #youtubeshorts #news #trending #bytewire");
  const shortTags = webhookPayload.tags || (ytMeta.tags || ["shorts", "news", "trending", "youtubeshorts", "bytewire"]);
  const videoDownloadUrl = "https://ytvideo.harikothapalli.space/api/download/" + video._id + "/short/" + singleShortIndex;

  return [{
    json: {
      isSingleShort: true,
      isFullVideoOnly: false,
      videoId: video._id,
      shortIndex: singleShortIndex,
      token: token,
      title: finalTitle.substring(0, 100),
      description: shortDesc.substring(0, 5000),
      tags: shortTags.slice(0, 15).map(t => String(t).trim()).filter(Boolean),
      categoryId: "25",
      privacyStatus: "public",
      madeForKids: false,
      videoDownloadUrl: videoDownloadUrl,
      shorts: [],
      shortsCount: 0
    }
  }];
}

const meta = video.youtubeMetadata || {};
const title = (meta.title || video.title || "Trending News Daily").substring(0, 100);
const description = (meta.description || "Top 3 " + video.subject + " news. Subscribe to ByteWire for daily updates! #news #trending").substring(0, 5000);
const tags = (meta.tags || ["news", "trending", "breaking news", "bytewire"]).slice(0, 15).map(t => String(t).trim()).filter(Boolean);
const videoDownloadUrl = "https://ytvideo.harikothapalli.space/api/download/" + video._id;

return [{
  json: {
    isSingleShort: false,
    isFullVideoOnly: true,
    videoId: video._id,
    title: title,
    description: description,
    tags: tags,
    categoryId: "25",
    privacyStatus: "public",
    madeForKids: false,
    videoDownloadUrl: videoDownloadUrl,
    thumbnailUrl: "https://ytvideo.harikothapalli.space/thumbnails/" + video._id + ".png",
    shorts: (video.shorts || []).slice(0, 3),
    shortsCount: Math.min(3, (video.shorts || []).length),
    token: token
  }
}];

const ytResult = $input.first().json;
const youtubeId = ytResult.uploadId || ytResult.id || "";
const preparedData = $("6. Prepare Video/Short Data").first().json;

if (preparedData.isSingleShort) {
  if (youtubeId && preparedData.videoId && preparedData.token) {
    try {
      await fetch("https://ytvideo.harikothapalli.space/api/video/" + preparedData.videoId + "/short/" + preparedData.shortIndex + "/youtube", {
        method: "PATCH",
        headers: { "Content-Type": "application/json", "Authorization": "Bearer " + preparedData.token },
        body: JSON.stringify({ youtubeShortId: youtubeId, youtubeShortUrl: "https://www.youtube.com/shorts/" + youtubeId })
      });
    } catch (_) {}
  }
  return [{
    json: {
      status: "success",
      type: "short",
      shortIndex: preparedData.shortIndex,
      youtubeShortId: youtubeId,
      youtubeShortUrl: "https://www.youtube.com/shorts/" + youtubeId,
      message: "Short #" + preparedData.shortIndex + " published successfully to YouTube!"
    }
  }];
}

// 6:00 AM Full Video upload complete
if (youtubeId && preparedData.videoId && preparedData.token) {
  try {
    await fetch("https://ytvideo.harikothapalli.space/api/video/" + preparedData.videoId + "/youtube", {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + preparedData.token },
      body: JSON.stringify({ youtubeVideoId: youtubeId })
    });
  } catch (_) {}
}

return [{
  json: {
    status: "success",
    type: "full_video",
    youtubeVideoId: youtubeId,
    youtubeUrl: "https://www.youtube.com/watch?v=" + youtubeId,
    message: "Full video uploaded successfully to YouTube at 6:00 AM! Shorts will be published individually at 9:00 AM, 2:00 PM, and 6:00 PM."
  }
}];

const result = $input.first().json;
return [{
  json: {
    status: "success",
    timestamp: new Date().toISOString(),
    ...result
  }
}];
